cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  // --- Premium: processing fee and base premiums per item type ---
  it.todo("quotes an empty item list as premium 5 G (processing fee only)");
  it.todo("quotes a single plain sword as premium 105 G (100 G base + 5 G fee)");
  it.todo("quotes a single plain amulet as premium 65 G (60 G base + 5 G fee)");
  it.todo("quotes a single plain staff as premium 85 G (80 G base + 5 G fee)");
  it.todo("quotes a single plain potion as premium 45 G (40 G base + 5 G fee)");
  it.todo("quotes a single rune as premium 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as premium 30 G (25 G base + 5 G fee)");
  it.todo("quotes a sword and an amulet as premium 165 G (100 + 60 base + 5 G fee)");

  // --- Building block of 3 alike components ---
  it.todo("quotes 2 runes as base premium 50 G (no block) -- premium 55 G");
  it.todo("quotes 3 runes as base premium 60 G (block applies) -- premium 65 G");
  it.todo("quotes 4 runes as base premium 100 G (no block; block requires exactly 3) -- premium 105 G");
  it.todo("quotes 7 runes as base premium 175 G -- premium 180 G");
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types) -- premium 80 G");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks) -- premium 125 G");

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge on the cursed item's base premium: cursed sword, 0 years, no prior contract -- premium 165 G");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5: sword enchantment 5 -- surcharge applies");
  it.todo("adds no high-enchantment surcharge at enchantment 4: sword enchantment 4 -- no surcharge");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -- base 160 G, curse adds 50 G -- 210 G before further modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge to each item in a quote regardless of customer history");
  it.todo("applies a 15 % follow-up-contract discount to each contract after the customer's first quote in the scenario");
  it.todo("applies no follow-up-contract discount to the customer's first quote in the scenario");

  // --- Rounding in the MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("keeps intermediate premium amounts as fractions and rounds only the final premium");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years, no prior contract) as premium 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed steel sword (enchantment 7) as premium 160 G");

  // --- Insurance sum and cap ---
  it.todo("caps a policy covering a sword at 2000 G (2 x insurance sum 1000 G)");
  it.todo("caps a policy covering a sword and an amulet at 3200 G (2 x insurance sum 1600 G)");
  it.todo("caps a policy covering two swords at 4000 G (2 x insurance sum 2000 G)");
  it.todo("caps a policy covering a sword and 3 runes at 3500 G (insurance sum 1750 G; block discount affects premium only)");
  it.todo("caps a cursed sword policy at 2000 G based on the unmodified insurance value, though its premium is 165 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a regular steel sword (enchantment 3) damaged by 500 G (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for a rune damaged by 200 G (no enchantment level or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -- payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses damage at 50 % for enchantment exactly 8: dragon sword, damage 1000 G -- payout 400 G");
  it.todo("reimburses steel sword enchantment 9 damaged by 1000 G at 50 % then deductible -- payout 400 G");
  it.todo("reimburses dragon-material sword enchantment 5 damaged by 800 G fully then deductible -- payout 700 G");
  it.todo("lets the 50 % rule win for dragon-material sword enchantment 9 damaged by 1000 G -- payout 400 G");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays out 1400 G and reports remainingCap 600 G for a first 1500 G claim on a sword policy (cap 2000 G)");
  it.todo("reduces a second 1500 G claim to the remaining cap: payout 600 G, remainingCap 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats each damage entry of the same item type as a separate damage with its own deductible: two sword damages on a two-sword policy");

  // --- Rounding of payouts ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");

  // --- CLI contract: success ---
  it.todo("CLI reads a scenario from stdin and writes results in step order to stdout, exiting with status 0");
  it.todo("CLI writes a quote result as {premium} and a claim result as {payout, remainingCap}");

  // --- CLI contract: rejections (non-zero exit, error description on stderr, no results on stdout) ---
  it.todo("CLI exits non-zero and writes an error to stderr when a quote item has an unknown type (e.g. broomstick), writing no results to stdout");
  it.todo("CLI exits non-zero and writes an error to stderr when a claim damages an item not covered by the policy (e.g. amulet damaged when only a sword is insured)");
  it.todo("CLI exits non-zero and writes an error to stderr when a claim damages an item with an unknown type");
  it.todo("CLI exits non-zero and writes an error to stderr when a claim has more damage entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("CLI exits non-zero and writes an error to stderr when a claim damage entry has a negative amount (-200)");
});
EOF
pnpm test 2>&1 | tail -15

