export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function mainItemBasePremium(item: Item): number {
  return MAIN_ITEM_BASE_PREMIUMS[item.type];
}

function componentsBasePremium(components: Item[]): number {
  return components.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : components.length * COMPONENT_BASE_PREMIUM;
}

function sum(amounts: number[]): number {
  return amounts.reduce((total, amount) => total + amount, 0);
}

function policyBasePremium(items: Item[]): number {
  return (
    sum(items.filter((item) => !isComponent(item)).map(mainItemBasePremium)) +
    componentsBasePremium(items.filter(isComponent))
  );
}

export function quote(_customer: Customer, items: Item[]): number {
  return policyBasePremium(items) + PROCESSING_FEE;
}
