import { describe, expect, it } from "vitest";
import { quote } from "./claim-office.js";

describe("MHPCO claim office", () => {
  // --- Premium: processing fee and base premiums per item type ---
  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
  });
  it("quotes a single plain sword as premium 105 G (100 G base + 5 G fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(105);
  });
  it("quotes a single plain amulet as premium 65 G (60 G base + 5 G fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(65);
  });
  it("quotes a single plain staff as premium 85 G (80 G base + 5 G fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(85);
  });
  it("quotes a single plain potion as premium 45 G (40 G base + 5 G fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(45);
  });
  it("quotes a single rune as premium 30 G (25 G base + 5 G fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(30);
  });
  it("quotes a single moonstone as premium 30 G (25 G base + 5 G fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }])).toBe(30);
  });
  it("quotes a sword and an amulet as premium 165 G (100 + 60 base + 5 G fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }, { type: "amulet" }])).toBe(165);
  });

  // --- Building block of 3 alike components ---
  it("quotes 2 runes as base premium 50 G (no block) -- premium 55 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(55);
  });
  it("quotes 3 runes as base premium 60 G (block applies) -- premium 65 G", () => {
    const runes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(65);
  });
  it("quotes 4 runes as base premium 100 G (no block; block requires exactly 3) -- premium 105 G", () => {
    const runes = Array.from({ length: 4 }, () => ({ type: "rune" }));
    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(105);
  });
  it("quotes 7 runes as base premium 175 G -- premium 180 G", () => {
    const runes = Array.from({ length: 7 }, () => ({ type: "rune" }));
    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(180);
  });
  it("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types) -- premium 80 G", () => {
    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(80);
  });
  it("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks) -- premium 125 G", () => {
    const items = [
      ...Array.from({ length: 3 }, () => ({ type: "rune" })),
      ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
    ];
    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(125);
  });

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge on the cursed item's base premium: cursed sword, 0 years, no prior contract -- premium 165 G");

