// Policy-wide modifiers apply to the policy base premium.
function firstInsuranceSurcharge(basePremium: number): number {
  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
}

function isLongStanding(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function loyaltyDiscount(customer: Customer, basePremium: number): number {
  return isLongStanding(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
}

// Policy-wide modifiers (loyalty, first insurance, and later the follow-up
// contract discount) all apply to the policy base premium. Returns the net
// adjustment: surcharges positive, discounts negative.
function policyWideModifiers(customer: Customer, basePremium: number): number {
  return (
    firstInsuranceSurcharge(basePremium) - loyaltyDiscount(customer, basePremium)
  );
}

