cat > src/scenario.ts <<'EOF'
// Running a scenario: the MHPCO processes a customer's steps in order, so a
// quote creates a policy that a later claim can be made against.

import { type Customer, quote } from "./claim-office.js";
import { type Damage, policyCap, settleClaim } from "./claim-settlement.js";
import { type Item } from "./item-catalogue.js";

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

// A policy, once quoted, carries its items and whatever cap it has left.
interface Policy {
  items: Item[];
  remainingCap: number;
}

export function runScenario(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  let contractsSoFar = 0;

  return scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const premium = quote(scenario.customer, step.items, contractsSoFar);
      contractsSoFar += 1;
      policies.set(index, {
        items: step.items,
        remainingCap: policyCap(step.items),
      });
      return { premium };
    }

    const policy = policies.get(step.policy) as Policy;
    const settlement = settleClaim(
      policy.items,
      step.incident.damages,
      policy.remainingCap,
    );
    policy.remainingCap = settlement.remainingCap;
    return settlement;
  });
}
EOF
cat > src/cli.ts <<'EOF'
#!/usr/bin/env node
// The claim-office command: reads a scenario as JSON on stdin and writes the
// corresponding results as JSON on stdout. Transport only -- every decision
// belongs to the domain modules it calls.

import { type Scenario, runScenario } from "./scenario.js";

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(Buffer.from(chunk));
  }
  return Buffer.concat(chunks).toString("utf8");
}

async function main(): Promise<void> {
  const scenario = JSON.parse(await readStdin()) as Scenario;
  const results = runScenario(scenario);
  process.stdout.write(`${JSON.stringify({ results })}\n`);
}

await main();
EOF
